<template>
  <v-card>
    <v-data-table
      flat
      :headers="headers"
      :items="filteredAlarmList"
      :items-per-page="10"
      class="mx-4"
    ></v-data-table>
  </v-card>
</template>

<script>
export default {
  props: ["bandinfo", "alarmList"],
  async mounted() {
    // this.alarmList = await this.getEventList();
  },
  computed: {
    filteredAlarmList() {
      // value가 0 또는 '0'인 항목 제외
      return this.alarmList.filter(
        (item) => item.value !== 0 && item.value !== "0"
      );
    },
  },
  data() {
    return {
      restapi: false,
      headers: [
        { text: "번호", align: "start", sortable: false, value: "id" },
        { text: "타입", value: "type" },
        { text: "날짜", value: "datetime" },
        { text: "값", value: "value" },
      ],
    };
  },
};
</script>
