<template>
  <v-data-table
    falt
    class="pa-1"
    height="23vh"
    :headers="headers"
    :items="getEventList"
    hide-default-footer
    :items-per-page="-1"
  ></v-data-table>
</template>

<script>
export default {
  props: ['eventList'],
  computed: {
    getEventList() {
      var el = []

      for (var i in this.eventList) {
        var type = null
        var value = ''
        switch (this.eventList[i].type) {
          case 1: {
            type = '배터리 충전 필요'
            value = this.eventList[i].value
            break
          }
          case 2: {
            type = '배터리 잔량 부족'
            value = this.eventList[i].value
            break
          }
          case 3: {
            type = '미착용 감지'
            break
          }
          case 5: {
            type = '네트워크 신호 약함'
            break
          }
          case 6: {
            if (value == 1) {
                type = '구조 요청'
              }
            break
          }
        }
        if (type != null) {
          el.push({
            bid: this.eventList[i].bandid,
            band_name: this.eventList[i].band_name,
            type: type,
            value: value,
          })
        }
      }
      return el
    },
  },
  data() {
    return {
      headers: [
        {
          text: '이름',
          align: 'start',
          sortable: false,
          value: 'band_name',
        },

        { text: '이벤트', value: 'type' },
        { text: '', value: 'value' },
      ],
    }
  },
}
</script>
<style lang="scss"></style>
