<template>
  <v-data-table
    class="pa-1"
    falt
    height="24vh"
    :headers="headers"
    :items="getEventList"
    hide-default-footer
    :items-per-page="-1"
  ></v-data-table>
</template>

<script>
export default {
  props: ['eventList'],
  mounted() {},

  computed: {
    getEventList() {
      var el = []
      for (var i in this.eventList) {
        var type = null
        var value = ''
        switch (this.eventList[i].type) {
          case 0: {
            type = '낙상 발생'
            value = '위험'
            break
          }
          case 4: {
            type = '심박수 이상'
            value = this.eventList[i].value >= 150 ? '위험' : '주의'
            break
          }
        }
        if (type != null) {
          el.push({
            bid: this.eventList[i].bandid,
            band_name: this.eventList[i].band_name,
            type: type,
            value: value,
          })
        }
      }
      return el
    },
  },
  data() {
    return {
      headers: [
        {
          text: '이름',
          align: 'start',
          sortable: false,
          value: 'band_name',
        },

        { text: '분류', value: 'type' },
        { text: '', value: 'value' },
      ],
    }
  },
}
</script>
<style lang="scss"></style>
