<template>
  <div>
    <v-toolbar flat class="primary">
      <v-toolbar-title class="text-uppercase font-weight-bold detail-header-text">
        사용자 정보
      </v-toolbar-title>
      <v-spacer></v-spacer>
      <v-list class="primary">
        <v-list-item>
          <v-list-item-content style="text-align: right">
            <v-list-item-title class="detail-sub-text">
              {{ userinfo.name }}
            </v-list-item-title>
            <v-list-item-subtitle v-text="userinfo.permission"></v-list-item-subtitle>
          </v-list-item-content>
        </v-list-item>
      </v-list>
    </v-toolbar>
    <div class="mx-4 mt-5">
      <v-divider></v-divider>
      <div class="mt-4">
        <v-row>
          <v-col cols="12" md="4">
            <v-card>
              <v-toolbar flat>
                <v-card-subtitle class="black--text font-weight-bold mt-n2 ml-n4 detail-text-style">
                  정보
                </v-card-subtitle>
                <v-spacer></v-spacer>
                <v-btn
                  class="mt-n2 font-weight-medium content-text-style"
                  text
                  color="point2"
                  depressed
                  @click="toggleEdit"
                >
                  {{ isEditing ? '저장' : '수정' }}
                </v-btn>
              </v-toolbar>

              <v-list class="mt-n4">
                <v-list-item>
                  <v-list-item-content class="content-text-style">
                    이름
                  </v-list-item-content>
                  <v-list-item-action class="content-text-style">
                    <template v-if="isEditing">
                      <v-text-field v-model="editedInfo.name" dense hide-details single-line></v-text-field>
                    </template>
                    <template v-else>
                      {{ userinfo.name }}
                    </template>
                  </v-list-item-action>
                </v-list-item>
                <v-list-item>
                  <v-list-item-content class="content-text-style">
                    UID
                  </v-list-item-content>
                  <v-list-item-action class="content-text-style">
                    {{ userinfo.uid }}
                  </v-list-item-action>
                </v-list-item>
                <v-list-item>
                  <v-list-item-content class="content-text-style">
                    사용자 아이디
                  </v-list-item-content>
                  <v-list-item-action class="content-text-style">
                    {{ userinfo.username }}
                  </v-list-item-action>
                </v-list-item>
                <v-list-item>
                  <v-list-item-content class="content-text-style">
                    이메일
                  </v-list-item-content>
                  <v-list-item-action class="content-text-style">
                    <template v-if="isEditing">
                      <v-text-field
                        v-model="editedInfo.email"
                        dense
                        hide-details
                        single-line
                        :rules="[rules.required, rules.email]"
                        type="email"
                      ></v-text-field>
                    </template>
                    <template v-else>
                      {{ userinfo.email }}
                    </template>
                  </v-list-item-action>
                </v-list-item>
                <v-list-item>
                  <v-list-item-content class="content-text-style">
                    전화번호
                  </v-list-item-content>
                  <v-list-item-action class="content-text-style">
                    <template v-if="isEditing">
                      <v-text-field
                        v-model="editedInfo.phone"
                        dense
                        hide-details
                        single-line
                        :rules="[rules.required, rules.phone]"
                        @input="formatPhoneNumber"
                        maxlength="13"
                      ></v-text-field>
                    </template>
                    <template v-else>
                      {{ userinfo.phone }}
                    </template>
                  </v-list-item-action>
                </v-list-item>
                <v-list-item>
                  <v-list-item-content class="content-text-style">
                    나이
                  </v-list-item-content>
                  <v-list-item-action class="content-text-style">
                    <template v-if="isEditing">
                      <v-text-field
                        v-model="editedInfo.age"
                        dense
                        hide-details
                        single-line
                        type="number"
                        :rules="[rules.required, rules.age]"
                      ></v-text-field>
                    </template>
                    <template v-else> {{ userinfo.age }}세 </template>
                  </v-list-item-action>
                </v-list-item>
                <v-list-item>
                  <v-list-item-content class="content-text-style">
                    성별
                  </v-list-item-content>
                  <v-list-item-action class="content-text-style">
                    <template v-if="isEditing">
                      <v-select
                        v-model="editedInfo.gender"
                        :items="genderOptions"
                        dense
                        hide-details
                        single-line
                      ></v-select>
                    </template>
                    <template v-else>
                      {{ userinfo.gender === 'M' ? '남성' : '여성' }}
                    </template>
                  </v-list-item-action>
                </v-list-item>
              </v-list>
            </v-card>
          </v-col>
          <v-col cols="12" md="8">
            <v-card>
              <v-toolbar class="mb-n4" flat>
                <v-toolbar-title class="detail-text-style black--text font-weight-bold">밴드</v-toolbar-title>
                <v-spacer></v-spacer>
                <v-btn depressed color="white" @click="bandDialog = true">
                  <v-icon>mdi-plus</v-icon>
                  등록
                </v-btn>
              </v-toolbar>
              <v-data-table class="mt-2" falt :headers="headers" :items="bandList" :items-per-page="3">
                <template v-slot:item.actions="{ item }">
                  <v-icon @click="deleteItem(item)" :size="setIconSize()">
                    mdi-delete
                  </v-icon>
                </template>
              </v-data-table>
            </v-card>
          </v-col>
        </v-row>
      </div>
    </div>

    <!-- 밴드 매칭 다이얼로그 추가 -->
    <v-dialog v-model="bandDialog" max-width="500px">
      <v-card>
        <v-card-title class="detail-text-style">
          밴드 등록
          <v-spacer></v-spacer>
          <v-btn icon @click="closeBandDialog">
            <v-icon>mdi-close</v-icon>
          </v-btn>
        </v-card-title>
        <v-card-text>
          <v-form ref="bandForm">
            <v-text-field
              v-model="bandMatch.name"
              label="이름"
              :rules="[rules.required]"
              dense
              class="mb-4"
            ></v-text-field>
            <v-text-field
              v-model="bandMatch.alias"
              label="별칭"
              :rules="[rules.required]"
              dense
              class="mb-4"
            ></v-text-field>
            <v-text-field
              v-model="bandMatch.bandId"
              label="밴드 ID"
              :rules="[rules.required]"
              dense
              class="mb-2"
            ></v-text-field>
          </v-form>
        </v-card-text>
        <v-card-actions>
          <v-spacer></v-spacer>
          <v-btn color="point2" text @click="matchBand">등록</v-btn>
        </v-card-actions>
      </v-card>
    </v-dialog>

    <!-- 매칭 해제 확인 다이얼로그 -->
    <v-dialog v-model="unmatchDialog" max-width="400">
      <v-card>
        <v-card-title class="headline">밴드 삭제 확인</v-card-title>
        <v-card-text>
          정말로 이 밴드를 삭제하시겠습니까?
        </v-card-text>
        <v-card-actions>
          <v-spacer></v-spacer>
          <v-btn color="grey darken-1" text @click="unmatchDialog = false">
            취소
          </v-btn>
          <v-btn color="warning" text @click="confirmUnmatch">
            해제
          </v-btn>
        </v-card-actions>
      </v-card>
    </v-dialog>
  </div>
</template>
<script>
export default {
  data() {
    return {
      userinfo: {
        id: '',
        uid: '',
        username: '',
        name: '',
        email: '',
        phone: '',
        age: '',
        gender: '',
        permission: '',
        group: null,
      },
      bandList: [],
      headers: [
        {
          text: '번호',
          align: 'start',
          sortable: true,
          value: 'num',
        },
        { text: '밴드 아이디', value: 'bid', sortable: true },
        { text: '별칭', value: 'alias', sortable: true },
        { text: '이름', value: 'name', sortable: true },
        { text: '', value: 'actions', sortable: false },
      ],
      isEditing: false,
      editedInfo: {
        name: '',
        email: '',
        phone: '',
        age: '',
        gender: '',
      },
      menu: false,
      rules: {
        required: (v) => !!v || '필수 입력 항목입니다',
        email: (v) => {
          const pattern = /^[0-9a-zA-Z]([-_.]?[0-9a-zA-Z])*@[0-9a-zA-Z]([-_.]?[0-9a-zA-Z])*\.[a-zA-Z]{2,3}$/
          return pattern.test(v) || '올바른 이메일 형식이 아닙니다'
        },
        phone: (v) => {
          const pattern = /^01([0|1|6|7|8|9])-?([0-9]{3,4})-?([0-9]{4})$/
          return pattern.test(v.replace(/-/g, '')) || '올바른 전화번호 형식이 아닙니다'
        },
        age: (v) => {
          const age = parseInt(v)
          return (age > 0 && age < 150) || '올바른 나이를 입력해주세요'
        },
      },
      genderOptions: [
        { text: '남성', value: 'M' },
        { text: '여성', value: 'F' },
      ],
      bandDialog: false,
      bandMatch: {
        name: '',
        alias: '',
        bandId: null,
      },
      availableBands: [], // 매칭 가능한 밴드 목록
      unmatchDialog: false,
      selectedItem: null,
    }
  },

  async mounted() {
    try {
      // SESSION 키에서 사용자 정보 가져오기
      const storedSession = localStorage.getItem('SESSION')
      if (!storedSession) {
        this.$router.push('/login')
        return
      }

      let userData
      try {
        userData = JSON.parse(storedSession)
      } catch (e) {
        console.error('세션 데이터 파싱 실패:', e)
        localStorage.removeItem('SESSION')
        this.$router.push('/login')
        return
      }

      if (!userData || !userData.id) {
        this.$router.push('/login')
        return
      }

      // 사용자 정보 설정
      this.userinfo = {
        id: userData.id,
        uid: userData.uid,
        username: userData.username,
        name: userData.name,
        email: userData.email,
        phone: userData.phone,
        age: userData.age,
        gender: userData.gender,
        permission: userData.permission,
        created: userData.created,
        last_login_time: userData.last_login_time,
      }

      // 수정 폼 초기값 설정
      this.editedInfo = {
        name: userData.name,
        email: userData.email,
        phone: userData.phone,
        age: userData.age,
        gender: userData.gender,
      }

      // 밴드 리스트는 한 번만 조회
      await this.getBandList()
    } catch (error) {
      console.error('사용자 정보 조회 실패:', error)
      this.$router.push('/login')
    }
  },

  methods: {
    async getBandList() {
      try {
        const response = await this.$http.get(`users/bandinfo/${this.userinfo.id}`)
        this.bandList = response.data.data || []
        this.bandList.forEach((band, index) => {
          band.num = index + 1
        })
      } catch (error) {
        console.error('밴드 목록 조회 실패:', error)
        this.bandList = []
      }
    },
    setIconSize() {
      switch (this.$vuetify.breakpoint.name) {
        case 'xs':
          return 20
        case 'sm':
          return 22
        case 'md':
          return 24
        case 'lg':
          return 28
        case 'xl':
          return 30
      }
    },
    toggleEdit() {
      if (this.isEditing) {
        this.saveChanges()
      } else {
        this.editedInfo = {
          name: this.userinfo.name,
          email: this.userinfo.email,
          phone: this.userinfo.phone,
          age: this.userinfo.age,
          gender: this.userinfo.gender,
        }
        this.isEditing = !this.isEditing
      }
    },

    async saveChanges() {
      // 유효성 검사
      if (!this.editedInfo.name?.trim()) {
        this.$toast.error('이름을 입력해주세요.')
        return
      }

      if (
        !this.rules.email(this.editedInfo.email) === true ||
        !this.rules.phone(this.editedInfo.phone) === true ||
        !this.rules.age(this.editedInfo.age) === true
      ) {
        this.$toast.error('입력 형식을 확인해주세요.')
        return
      }

      try {
        const response = await this.$http.put(`/users/${this.userinfo.id}`, {
          name: this.editedInfo.name,
          email: this.editedInfo.email,
          phone: this.editedInfo.phone,
          age: parseInt(this.editedInfo.age),
          gender: this.editedInfo.gender,
        })

        if (response.data.status === true) {
          // 로컬 스토리지의 세션 정보도 업데이트
          const sessionData = JSON.parse(localStorage.getItem('SESSION'))
          const updatedSessionData = {
            ...sessionData,
            name: this.editedInfo.name,
            email: this.editedInfo.email,
            phone: this.editedInfo.phone,
            age: parseInt(this.editedInfo.age),
            gender: this.editedInfo.gender,
          }
          localStorage.setItem('SESSION', JSON.stringify(updatedSessionData))

          // UI 업데이트
          Object.assign(this.userinfo, {
            name: this.editedInfo.name,
            email: this.editedInfo.email,
            phone: this.editedInfo.phone,
            age: parseInt(this.editedInfo.age),
            gender: this.editedInfo.gender,
          })

          this.isEditing = false
          this.$toast.success('사용자 정보가 성공적으로 수정되었습니다.')
        } else {
          throw new Error(response.data.message || '사용자 정보 수정에 실패했습니다.')
        }
      } catch (error) {
        console.error('사용자 정보 수정 실패:', error)
        const errorMessage = error.response?.data?.message || '사용자 정보 수정에 실패했습니다.'
        this.$toast.error(errorMessage)
      }
    },

    setUserInfo(userData) {
      this.userinfo = {
        id: userData.id,
        uid: userData.uid,
        username: userData.username,
        name: userData.name,
        email: userData.email,
        phone: userData.phone,
        age: userData.age,
        gender: userData.gender,
        permission: userData.permission,
        created: userData.created,
        last_login_time: userData.last_login_time,
        group: userData.group,
      }

      this.editedInfo = {
        name: userData.name,
        email: userData.email,
        phone: userData.phone,
        age: userData.age,
        gender: userData.gender,
      }
    },

    closeBandDialog() {
      this.bandDialog = false
      this.bandMatch = {
        name: '',
        alias: '',
        bandId: null,
      }
      this.$refs.bandForm?.reset()
    },

    async matchBand() {
      if (!this.$refs.bandForm.validate()) return

      try {
        await this.$http.post(`/users/${this.userinfo.id}/bands`, {
          name: this.bandMatch.name,
          bandId: this.bandMatch.bandId,
          alias: this.bandMatch.alias,
        })

        this.$toast.success('밴드 등록에 성공했습니다.')
        this.bandDialog = false // 다이얼로그 닫기
        await this.getBandList() // 밴드 목록 새로고침
      } catch (error) {
        this.$toast.error('밴드 등록에 실패했습니다.')
      }
    },

    deleteItem(item) {
      this.selectedItem = item
      this.unmatchDialog = true
    },

    async confirmUnmatch() {
      try {
        const response = await this.$http.delete(`users/${this.userinfo.id}/band-matching/${this.selectedItem.bid}`)

        if (response.data.status) {
          this.$toast.success('밴드가 삭제되었습니다.')
          await this.getBandList()
        } else {
          throw new Error(response.data.message)
        }
      } catch (error) {
        console.error('밴드 삭제 실패:', error)
        this.$toast.error('밴드 삭제에 실패했습니다.')
      } finally {
        this.unmatchDialog = false
        this.selectedItem = null
      }
    },
  },
}
</script>
